# Applying a CardData Texture2D to a 3D MeshInstance3D:
extends Node3D

@onready var mesh_instance: MeshInstance3D = $MeshInstance3D

func apply_card_surface_3d(data: CardData) -> void:
    var mat := StandardMaterial3D.new()
    var tex: Texture2D = data.resolve_downloaded_texture()
    if tex != null:
        mat.albedo_texture = tex
    else:
        mat.albedo_color = Color("#FF6B78") if data.is_red_suit() else Color("#ECF2F8")
    mat.roughness = 0.35
    mesh_instance.material_override = mat

