# Complete 3D Character Controller in Godot 4.3:
extends CharacterBody3D

@export var speed: float = 6.0
@export var jump_velocity: float = 7.5
@export var gravity: float = 18.0

func _physics_process(delta: float) -> void:
    if not is_on_floor():
        velocity.y -= gravity * delta
    elif Input.is_action_just_pressed("jump"):
        velocity.y = jump_velocity

    var input_2d: Vector2 = Input.get_vector("move_left", "move_right", "move_forward", "move_back")
    var move_dir: Vector3 = (transform.basis * Vector3(input_2d.x, 0.0, input_2d.y)).normalized()
    if move_dir != Vector3.ZERO:
        velocity.x = move_dir.x * speed
        velocity.z = move_dir.z * speed
    else:
        velocity.x = move_toward(velocity.x, 0.0, speed)
        velocity.z = move_toward(velocity.z, 0.0, speed)
    move_and_slide()

# Clickable & Hoverable 3D Playing Card (Area3D):
extends Area3D
signal card_3d_clicked(card_node: Node3D)

var is_selected: bool = false

func _ready() -> void:
    mouse_entered.connect(_on_mouse_entered)
    mouse_exited.connect(_on_mouse_exited)
    input_event.connect(_on_input_event)

func _on_mouse_entered() -> void:
    if not is_selected:
        create_tween().tween_property(self, "position:y", 0.08, 0.10)

func _on_mouse_exited() -> void:
    if not is_selected:
        create_tween().tween_property(self, "position:y", 0.0, 0.10)

func _on_input_event(_cam: Node, event: InputEvent, _pos: Vector3, _norm: Vector3, _idx: int) -> void:
    if event is InputEventMouseButton and event.button_index == MOUSE_BUTTON_LEFT and event.pressed:
        card_3d_clicked.emit(self)

# 3D Kadi Tabletop Controller Reusing 100% of GameState & RuleValidator:
extends Node3D

@onready var hand_root_3d: Node3D = $HandArcRoot3D
@onready var discard_anchor_3d: Node3D = $DiscardAnchor3D

func layout_human_hand_3d(cards_3d: Array[Node3D]) -> void:
    var n: int = cards_3d.size()
    for i in range(n):
        var offset: float = float(i) - float(n - 1) * 0.5
        cards_3d[i].position = Vector3(offset * 0.22, 0.10, 0.65 + absf(offset) * 0.025)
        cards_3d[i].rotation_degrees = Vector3(-28.0, -offset * 4.5, -offset * 3.0)

